add_filter( 'woocommerce_email_headers', 'perfectpixel_cc_bcc_recipients', 10, 2 );

function perfectpixel_cc_bcc_recipients( $headers, $email_id ) {
	$emails = array_filter( array_map( 'trim', explode( ',', '{{cc_bcc_emails}}' ) ) );
	if ( ! in_array( $email_id, $emails, true ) ) {
		return $headers;
	}
	foreach ( array( 'Cc' => '{{cc_addresses}}', 'Bcc' => '{{bcc_addresses}}' ) as $type => $list ) {
		$valid = array_filter( array_map( 'sanitize_email', explode( ',', $list ) ), 'is_email' );
		if ( $valid ) {
			$headers .= $type . ': ' . implode( ', ', $valid ) . "\r\n";
		}
	}
	return $headers;
}
